//! Source-borrowing CSS/SVG color parser. `currentColor` is context dependent.

use vexel_base::Span;
mod named_colors;
use named_colors::NAMED_COLORS;

const MAX_VALUE_BYTES: usize = 256;

/// Parse one CSS/SVG color value within an original source span.
/// The source is borrowed and never copied; malformed spans and values return `None`.
pub fn parse_color(source: &[u8], span: Span) -> Option<[u8; 4]> {
    let raw = span.slice(source)?;
    if raw.is_empty() || raw.len() > MAX_VALUE_BYTES { return None; }
    let start = raw.iter().position(|b| !ws(*b))?;
    let end = raw.iter().rposition(|b| !ws(*b))? + 1;
    let value = &raw[start..end];
    if eq_ci(value, b"transparent") { return Some([0, 0, 0, 0]); }
    if value[0] == b'#' { return parse_hex(value); }
    if value.contains(&b'(') { return parse_function(value); }
    NAMED_COLORS.iter().find_map(|(name, rgb)| {
        eq_ci(value, name.as_bytes()).then_some([(rgb >> 16) as u8, (rgb >> 8) as u8, *rgb as u8, 255])
    })
}

fn ws(b: u8) -> bool { matches!(b, b' ' | b'\t' | b'\r' | b'\n' | 0x0c) }
fn eq_ci(a: &[u8], b: &[u8]) -> bool { a.len() == b.len() && a.iter().zip(b).all(|(x,y)| x.to_ascii_lowercase() == *y) }
fn hex(b: u8) -> Option<u8> { match b { b'0'..=b'9' => Some(b-b'0'), b'a'..=b'f' => Some(b-b'a'+10), b'A'..=b'F' => Some(b-b'A'+10), _ => None } }
fn parse_hex(v: &[u8]) -> Option<[u8;4]> {
    if !matches!(v.len(),4|5|7|9) { return None; }
    let short=v.len()<=5; let count=if matches!(v.len(),5|9) {4} else {3}; let mut out=[0;4];
    for (i,c) in out.iter_mut().take(count).enumerate() {
        let at=1+i*(if short {1}else{2}); let hi=hex(*v.get(at)?)?;
        *c=if short {hi*17} else {hi*16+hex(*v.get(at+1)?)?};
    }
    if count==3 {out[3]=255;} Some(out)
}

